package storage

// PkeyColumn is the primary key column every physical table carries,
// generated by the server and never a source column.
const PkeyColumn = "__pkey"

// ogcFIDColumn is the feature-id column GDAL/OGR injects on almost every
// vector format duckdb/tables' CreateFromFile reads through ST_Read
// (GeoJSON, Shapefile, GeoPackage, CSV), geometry or not — a driver
// implementation detail, never something a caller asked to store.
const ogcFIDColumn = "OGC_FID"

// hiddenColumns are physical columns the server manages internally and
// never surfaces to a caller. Both stay in the physical table — only
// display excludes them.
var hiddenColumns = map[string]bool{
	PkeyColumn:   true,
	ogcFIDColumn: true,
}

// IsHiddenColumn reports whether name is a column the server manages
// internally and never surfaces to a caller.
func IsHiddenColumn(name string) bool {
	return hiddenColumns[name]
}
